<script setup lang="ts">
import { onMounted, reactive, ref } from "vue";
import { fetchDeploymentSettings, updateDeploymentSettings, type OidcProviderSetting } from "../../services/deploymentSettings";
const loading=ref(true),saving=ref(false),error=ref<string|null>(null),saved=ref(false);const browserOrigin=window.location.origin;
const login=reactive({default_login_method:"local"});const providers=ref<OidcProviderSetting[]>([]);
function newProvider():OidcProviderSetting{return{name:"",slug:"",issuer_url:"",client_id:"",client_secret:"",scopes:"openid profile email",redirect_uri:null,groups_claim:"groups",admin_group:null,user_match_field:"email",allow_new_users:true,button_text:"Continue with SSO",button_image_url:null,enabled:true,show_on_login:true,client_secret_configured:false}}
function slugify(name:string){return name.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"").slice(0,80)}
function addProvider(){providers.value.push(newProvider())}
function removeProvider(index:number){providers.value.splice(index,1)}
function defaultProviderSlug(provider:OidcProviderSetting){if(!provider.slug)provider.slug=slugify(provider.name)}
function ensureSlugs(){const used=new Set<string>();providers.value.forEach((p,i)=>{let base=slugify(p.slug||p.name)||`provider-${i+1}`,slug=base,n=2;while(used.has(slug)){slug=`${base}-${n++}`}p.slug=slug;used.add(slug)})}
onMounted(async()=>{try{const r=await fetchDeploymentSettings();login.default_login_method=r.oidc.default_login_method==="sso"?"sso":"local";providers.value=(r.oidc.named_providers??[]).map(p=>({...p,client_secret:""}));}catch(e){error.value=e instanceof Error?e.message:"Failed to load OIDC settings."}finally{loading.value=false}})
async function save(){saving.value=true;error.value=null;saved.value=false;try{ensureSlugs();const r=await updateDeploymentSettings({oidc_default_login_method:login.default_login_method,oidc_providers_json:JSON.stringify(providers.value)});providers.value=(r.oidc.named_providers??[]).map(p=>({...p,client_secret:""}));saved.value=true}catch(e){error.value=e instanceof Error?e.message:"Failed to save OIDC settings."}finally{saving.value=false}}
</script>
<template><section class="section"><h2>OpenID Connect / SSO</h2><p class="hint">Configure one or more named identity providers. Each provider contains its own OIDC settings, login presentation and direct autostart URLs. Client secrets stay encrypted on the backend.</p><div v-if="loading">Loading…</div><template v-else><div class="login-panel"><div><strong>Default login method</strong><p class="hint">Choose whether the normal login page initially prioritises local credentials or SSO.</p></div><select v-model="login.default_login_method"><option value="local">Local username &amp; password</option><option value="sso">SSO</option></select></div><div class="providers-header"><div><h3>Identity providers</h3><p class="hint">Add a provider to create its complete configuration card. The provider name supplies the slug when the slug is left blank.</p></div><button type="button" @click="addProvider">+ Add provider</button></div><div v-if="!providers.length" class="empty">No named providers configured. Click <strong>+ Add provider</strong> to create one.</div><div v-for="(provider,index) in providers" :key="index" class="provider-card"><div class="provider-card-head"><div><strong>{{ provider.name||`Provider ${index+1}` }}</strong><small>{{ provider.slug?`/${provider.slug}`:"Slug will be generated from the name" }}</small></div><button type="button" class="remove" @click="removeProvider(index)">Remove</button></div><div class="grid"><label><span>Provider name</span><input v-model="provider.name" placeholder="Authentik" @blur="defaultProviderSlug(provider)" /></label><label><span>Slug</span><input v-model="provider.slug" placeholder="authentik" autocomplete="off" /></label><label><span>Issuer / discovery URL</span><input v-model="provider.issuer_url" placeholder="https://id.example.com" /></label><label><span>Client ID</span><input v-model="provider.client_id" /></label><label><span>Client secret</span><input v-model="provider.client_secret" type="password" :placeholder="provider.client_secret_configured?'Leave blank to keep saved secret':'Required'" /></label><label><span>Scopes</span><input v-model="provider.scopes" /></label><label><span>Groups claim</span><input v-model="provider.groups_claim" placeholder="groups" /></label><label><span>Admin group</span><input v-model="provider.admin_group" placeholder="archive-admins" /></label><label><span>User matching</span><select v-model="provider.user_match_field"><option value="email">Email</option><option value="username">Username</option></select></label><label><span>Login button text</span><input v-model="provider.button_text" placeholder="Continue with Authentik" /></label><label><span>Button image URL</span><input v-model="provider.button_image_url" placeholder="Optional" /></label><label class="full"><span>Redirect URI</span><input v-model="provider.redirect_uri" :placeholder="`${browserOrigin}/api/auth/oidc/callback/${provider.slug||'authentik'}`" /></label></div><div class="provider-options"><label><input v-model="provider.allow_new_users" type="checkbox" /> Allow new users</label><label><input v-model="provider.enabled" type="checkbox" /> Provider enabled</label><label><input v-model="provider.show_on_login" type="checkbox" /> Show on login page</label></div><div class="autostart"><strong>Autostart URLs</strong><span><code>{{ browserOrigin }}/login/oidcstart/{{ provider.slug||slugify(provider.name)||'provider-slug' }}</code></span><span><code>{{ browserOrigin }}/login/{{ provider.slug||slugify(provider.name)||'provider-slug' }}</code></span><small>Both URLs start this provider directly. Uncheck “Show on login page” to keep it available by URL without showing it as a login-page choice.</small></div></div><p v-if="error" class="error">{{ error }}</p><p v-if="saved" class="success">OIDC settings saved.</p><button :disabled="saving" @click="save">{{ saving?"Saving…":"Save OIDC settings" }}</button></template></section></template>
<style scoped>.section{display:flex;flex-direction:column;gap:16px}.section h2{margin:0;color:#fff}.hint{color:#999;font-size:13px;line-height:1.5}.login-panel,.provider-card{border:1px solid #2f2f2f;border-radius:10px;padding:16px;background:#151515}.login-panel{display:flex;justify-content:space-between;align-items:center;gap:20px}.login-panel select,.grid input,.grid select{background:#111;border:1px solid #3a3a3a;border-radius:8px;color:#fff;padding:10px;font:inherit}.providers-header{display:flex;align-items:center;justify-content:space-between;gap:20px}.providers-header h3{margin:0;color:#fff}.providers-header .hint{margin:4px 0 0}.providers-header button,button{background:#d68a34;border:0;border-radius:8px;padding:10px 14px;font-weight:600;cursor:pointer}.provider-card-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.provider-card-head small{display:block;color:#777;margin-top:3px}.remove{background:transparent!important;border:1px solid #633!important;color:#fca5a5!important}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.grid label{display:flex;flex-direction:column;gap:6px;color:#ccc;font-size:13px}.grid label.full{grid-column:1/-1}.provider-options{display:flex;gap:18px;flex-wrap:wrap;margin-top:14px;color:#bbb;font-size:13px}.provider-options label{display:flex;align-items:center;gap:6px}.provider-options input{accent-color:#d68a34}.autostart{margin-top:14px;padding:12px;border:1px solid #333;border-radius:8px;background:#111;display:flex;flex-direction:column;gap:5px;color:#ccc;font-size:12px}.autostart strong{color:#fff}.autostart code{color:#d68a34;overflow-wrap:anywhere}.autostart small{color:#777}.empty{border:1px dashed #3a3a3a;border-radius:10px;padding:24px;color:#888;text-align:center}.error{color:#fca5a5}.success{color:#86efac}button:disabled{opacity:.6}@media(max-width:760px){.grid{grid-template-columns:1fr}.grid label.full{grid-column:auto}.providers-header,.login-panel{align-items:flex-start;flex-direction:column}}
</style>